const keys = Array.isArray(args) && args.length ? args : Object.keys(DIMENSIONS)
log(`Domaines : ${keys.join(', ')}`)

phase('Audit par domaine')
const results = await pipeline(keys, (key) => {
  const d = DIMENSIONS[key]
  if (!d) throw new Error('Domaine inconnu : ' + key)
  return agent(SOCLE(key, d.port) + '\n\n' + d.prompt, {
    label: 'audit:' + key,
    phase: 'Audit par domaine',
    model: MODEL,
    effort: 'high',
    schema: FINDINGS_SCHEMA,
  }).then((r) => (r ? { key, ...r } : { key, echec: true }))
})

const ok = results.filter(Boolean)
log(`Terminé : ${ok.filter((r) => !r.echec).length}/${keys.length} domaines avec résultat`)
return ok
